-- KO-225 group 5: translate Indonesian-only body payloads for English learners (batch 01).
update public.content_variants set body = $json${"text":"Andi has a portfolio consisting of bank stocks (BBCA), telecommunications stocks (TLKM), money market mutual funds, and government bonds. When technology stock prices drop, the impact is not too significant because his money is spread across various types of assets.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee","07f09c6e-6a98-4fe1-b38f-0868f149ca3e"]}$json$::jsonb where id = '0228382f-0eac-4221-93e4-7b5502f778d5';
update public.content_variants set body = $json${"text":"Ahmad started saving Rp 500,000 per month in a money market mutual fund since he was 20 years old. His friend Bayu started saving the same amount at the age of 30. Due to compound interest, Ahmad has a larger amount by the age of 40 even though their total deposits are not much different.","source_ids":["eca56a9e-df9b-432f-b360-c1ab6450a2ae","47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '064c3aca-12ee-4e89-83ea-453ad76f782a';
update public.content_variants set body = $json${"text":"A young family in Tangerang sets aside 10% of their salary for an emergency fund before paying bills. After 1 year, they have a reserve of 3 months' expenses.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953","53eef1ac-2553-48d9-92a0-af6159d7d369"]}$json$::jsonb where id = '0ec8cfea-0661-4950-954f-627beaea36b5';
update public.content_variants set body = $json${"type":"matching","pairs":[["Open","Stock price when the market opens"],["High","Highest price of the day"],["Volume","Number of shares traded"],["Market cap","Total company value in the market"]],"answer":{"High":"Highest price of the day","Open":"Stock price when the market opens","Volume":"Number of shares traded","Market cap":"Total company value in the market"},"question":"Match the stock terms with their meanings.","difficulty":"intermediate","explanation":"Understanding basic terms for reading a stock page is very important before investing."}$json$::jsonb where id = '1617cfb0-6c0c-4b02-bad3-2480bbdc9e4d';
update public.content_variants set body = $json${"text":"Dewi has an emergency fund of 6 months' expenses in savings, so she doesn't need to sell her stock investments when she needs urgent money. An emergency fund protects long-term investments.","source_ids":["7f4b83f2-8f1d-415c-9d4f-64e6284bef04","47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '2917dfcc-ab04-4fff-b4a3-6c758dd94d8e';
update public.content_variants set body = $json${"text":"Rina, a high school student in Surabaya, receives an allowance of Rp 800,000 per week. She saves Rp 200,000 in a digital wallet for transport and lunch, Rp 100,000 for phone credit and internet data, and Rp 500,000 for savings. When her friend offered an investment with a guaranteed return of 20% per month, Rina declined and checked the company's license on the OJK website.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953","9ddb5412-52b8-4461-b2e5-a5443ac63ca8"]}$json$::jsonb where id = '2a7e52dc-5292-4c97-99fb-a1091f8ae199';
update public.content_variants set body = $json${"text":"Doni almost transferred Rp 1 million to an account number sent via WhatsApp by a bank \"customer service\". He stopped and immediately contacted the official bank call center. It turned out to be a scam.","source_ids":["9ddb5412-52b8-4461-b2e5-a5443ac63ca8","337c397d-743e-4d1b-8344-09e47b95be90"]}$json$::jsonb where id = '34999ab5-5bbe-46ac-b73c-0748cfbc3fb2';
update public.content_variants set body = $json${"text":"Budi works as an intern with a salary of Rp 1,200,000 per month. Every payday, he immediately transfers Rp 200,000 to a separate savings account. After 6 months, Budi has an emergency fund of Rp 1,200,000 for health costs or urgent needs.","source_ids":["7f4b83f2-8f1d-415c-9d4f-64e6284bef04","53eef1ac-2553-48d9-92a0-af6159d7d369"]}$json$::jsonb where id = '362d9dd4-e56a-40c5-bc96-ec044093c5b3';
update public.content_variants set body = $json${"text":"Budi, a first-semester student in Jakarta, receives a monthly allowance of Rp 1,500,000. He writes a list of expenses: transport Rp 400,000 (needs), campus lunch Rp 600,000 (needs), streaming subscription Rp 100,000 (wants), and weekend hangout fund Rp 200,000 (wants). By separating needs and wants, Budi sets aside Rp 200,000 for an emergency savings.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953","7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}$json$::jsonb where id = '3a4e0d8a-0676-4092-9cd2-4940da762450';
update public.content_variants set body = $json${"text":"In 2021, the price of one liter of packaged cooking oil in traditional markets was around Rp 10,000. By 2023, the price rose to more than Rp 17,000 per liter. This increase in cooking oil prices is an example of inflation affecting the purchasing power of Indonesian people, especially families with tight daily expenses.","source_ids":["e49fe239-c534-4bed-b0bd-a7950b9e35c4","097b62c4-9aae-4933-a870-ac74a526b8f1"]}$json$::jsonb where id = '5f0f9f70-20be-4e67-b38d-1989e4fa41d3';
